begin;
create function public.cgf_intake_acceptance_audit_failure() returns trigger language plpgsql set search_path='' as $$begin if new.new_data->>'reason'='Application acceptance forced audit failure' then raise exception 'Forced application audit failure'; end if; return new; end$$;
create trigger cgf_intake_acceptance_audit_failure before insert on public.audit_trail for each row execute function public.cgf_intake_acceptance_audit_failure();
do $$
declare administrator uuid; bank uuid; branch uuid; sector uuid; application uuid:=gen_random_uuid(); failed_application uuid:=gen_random_uuid(); draft uuid:=gen_random_uuid(); tin text; form jsonb; receipt jsonb; member record; identity_count integer:=0; borrower uuid;
begin
 select p.id into administrator from public.profiles p join public.roles r on r.id=p.role_id where p.is_active and p.bank_id is null and r.is_active and r.code='super_admin' and r.tier=1 limit 1;
 select id into bank from public.banks where is_active order by id limit 1;
 branch:=gen_random_uuid();
 insert into public.bank_branches(id,bank_id,code,name_en,is_active) values(branch,bank,'APPQA_'||substr(branch::text,1,8),'Application acceptance branch',true);
 select id into sector from public.sectors where is_active and not is_prohibited limit 1;
 if administrator is null or bank is null or sector is null then raise exception 'Active administrator, eligible bank/branch and sector are required';end if;
 loop tin:=(100000000+floor(random()*899999999))::bigint::text;exit when not exists(select 1 from public.borrowers where tin_number=tin);end loop;
 form:=jsonb_build_object('legalEntityType','legal_entity','clientName','APPLICATION_QA_'||application::text,'clientTin',tin,'registrationNumber','QA','sectorId',sector,'addressStreet','QA street','city','QA city','district','QA district','workforce','2','establishmentYear','2000','businessDescription','QA business evidence','phone','+992901234567','email','qa@finance.tj','bankCustomerCode','','isBlacklisted',false,'blacklistReason','','guaranteeType','individual','legalRepSurname','QA','legalRepName','Representative','legalRepPatronymic','','legalRepGender','male','legalRepBirthdate','1980-01-01','legalRepCountry','Tajikistan','legalRepTin','123456789','passportNumber','QA-PASSPORT','bankId',bank,'branchId',branch,'productId','','requestedAmount','10000','currency','TJS','loanTerm','12','gracePeriod','0','frequency','monthly','repaymentMethod','annuity','interestRate','0','guaranteeCoverage','50','loanOfficer','','purpose','working_capital','purposeDetails','QA purpose','applicationDate',current_date::text,'bankApprovalDate',current_date::text,'annualTurnover','0','netIncome','-1','riskRating','A','totalExposure','0','collateralDescription','QA collateral','covenantBank','QA bank covenant','covenantPrsf','QA fund covenant','guarantors','[{"name":"QA Guarantor","id_number":"QA","relationship":"Owner"}]'::jsonb,'notes','QA notes');
 perform set_config('request.jwt.claim.sub',administrator::text,true);perform set_config('request.jwt.claim.role','authenticated',true);set local role authenticated;
 insert into public.loan_drafts(id,user_id,draft_name,form_data) values(draft,administrator,'APPLICATION_QA',form);
 receipt:=public.cgf_save_application(application,form,null,null,draft,'Application acceptance create');
 if receipt->>'id'<>application::text or receipt->>'status'<>'draft' or receipt->>'revision'<>'0' then raise exception 'Create receipt failed';end if;
 if exists(select 1 from public.loan_drafts where id=draft) then raise exception 'Draft was not retired';end if;
 if not exists(select 1 from public.loan_applications where id=application and intake_data=form and approved_amount=10000 and guarantee_amount=5000 and interest_rate=0 and grace_period_months=0) then raise exception 'Complete snapshot or explicit zero lost';end if;
 receipt:=public.cgf_save_application(application,form,null,null,draft,'Application acceptance create');if receipt->>'replayed'<>'true' then raise exception 'Create replay failed';end if;
 form:=form||'{"establishmentYear":"2001","notes":"Corrected evidence"}';
 receipt:=public.cgf_save_application(application,form,0,'draft',null,'Application acceptance correction');if receipt->>'revision'<>'1' then raise exception 'Correction revision failed';end if;
 receipt:=public.cgf_save_application(application,form,0,'draft',null,'Application acceptance correction');if receipt->>'replayed'<>'true' then raise exception 'Correction replay failed';end if;
 begin perform public.cgf_save_application(application,form||'{"notes":"Stale"}',0,'draft',null,'Application acceptance stale');raise exception 'Stale correction accepted';exception when serialization_failure then null;end;
 begin perform public.cgf_save_application(application,form||'{"clientTin":"987654321"}',1,'draft',null,'Application acceptance identity change');raise exception 'Borrower identity change accepted';exception when check_violation then null;end;
 begin perform public.cgf_save_application(failed_application,form||jsonb_build_object('clientTin',case when tin='111111111' then '222222222' else '111111111' end,'clientName','APPLICATION_QA_'||failed_application::text),null,null,null,'Application acceptance forced audit failure');raise exception 'Audit failure was ignored';exception when raise_exception then if sqlerrm<>'Forced application audit failure' then raise;end if;end;
 if exists(select 1 from public.loan_applications where id=failed_application) then raise exception 'Failed intake left a parent';end if;
 begin perform public.cgf_save_application(gen_random_uuid(),form||'{"currency":"USD"}',null,null,null,'Application acceptance currency');raise exception 'Unsupported currency accepted';exception when invalid_parameter_value then null;end;
 begin perform public.cgf_save_application(gen_random_uuid(),form||'{"guaranteeCoverage":"0"}',null,null,null,'Application acceptance zero coverage');raise exception 'Zero coverage silently defaulted';exception when invalid_parameter_value then null;end;
 if not exists(select 1 from public.cgf_search_applications(form->>'clientName') where id=application) then raise exception 'Borrower search failed';end if;
 begin update public.loan_applications set status='submitted' where id=application;raise exception 'Missing package accepted';exception when check_violation then null;end;
 reset role;
 select borrower_id into borrower from public.loan_applications where id=application;
 if (select count(*) from public.audit_trail where table_name='loan_applications' and record_id=application and changed_by=administrator and action in ('INSERT','UPDATE'))<>2 then raise exception 'Intake audit count or attribution incorrect';end if;
 if exists(select 1 from public.borrowers where name='APPLICATION_QA_'||failed_application::text) then raise exception 'Failed intake left a borrower';end if;
 alter table public.loan_applications disable trigger cgf_pipeline_guard;alter table public.loan_applications disable trigger cgf_application_boundary;alter table public.loan_applications disable trigger cgf_signed_loan_status;
 update public.loan_applications set status='guarantee_issued',guarantee_issued_date=current_date where id=application;
 alter table public.loan_applications enable trigger cgf_pipeline_guard;alter table public.loan_applications enable trigger cgf_application_boundary;alter table public.loan_applications enable trigger cgf_signed_loan_status;
 for member in select p.id,p.bank_id,r.code from public.profiles p join public.roles r on r.id=p.role_id where p.is_active and r.is_active and p.id<>administrator loop
  perform set_config('request.jwt.claim.sub',member.id::text,true);set local role authenticated;
  if member.code not in ('bank_admin','bank_officer') then
   begin update public.loan_applications set status='active',disbursement_date=current_date,disbursed_amount=10000,maturity_date=current_date+365 where id=application;if found then raise exception 'Unauthorized lifecycle accepted';end if;exception when insufficient_privilege then null;end;
  end if;
  begin perform public.cgf_save_application(application,form,1,'draft',null,'Application acceptance role denial');raise exception 'Role or reviewed-state correction accepted';exception when insufficient_privilege or serialization_failure then null;end;
  reset role;identity_count:=identity_count+1;
 end loop;
 perform set_config('request.jwt.claim.sub',administrator::text,true);set local role authenticated;
 begin update public.loan_applications set approved_amount=20000 where id=application;raise exception 'Reviewed terms changed';exception when insufficient_privilege then null;end;
 begin update public.loan_applications set disbursed_amount=100 where id=application;raise exception 'Same-state financial edit accepted';exception when insufficient_privilege then null;end;
 begin update public.loan_applications set status='settled',settlement_date=current_date,settlement_amount=0,authority_reason='Application acceptance invalid jump' where id=application;raise exception 'Invalid lifecycle jump accepted';exception when check_violation then null;end;
 update public.loan_applications set status='active',disbursement_date=current_date,disbursed_amount=10000,maturity_date=current_date+365,authority_reason='Application acceptance disbursement' where id=application;
 if not exists(select 1 from public.loan_applications where id=application and status='active') then raise exception 'Disbursement failed';end if;
 update public.loan_applications set status='rescheduled',reschedule_date=current_date,new_maturity_date=current_date+400,reschedule_reason='QA later maturity',authority_reason='Application acceptance reschedule' where id=application;
 update public.loan_applications set status='settled',settlement_date=current_date,settlement_amount=0,authority_reason='Application acceptance settlement' where id=application;
 if not exists(select 1 from public.loan_applications where id=application and status='settled' and settlement_amount=0) then raise exception 'Zero settlement lost';end if;
 reset role;
 if has_function_privilege('anon','public.cgf_save_application(uuid,jsonb,bigint,text,uuid,text)','EXECUTE') or has_function_privilege('anon','public.cgf_search_applications(text)','EXECUTE') then raise exception 'Anonymous execution grant';end if;
 raise notice 'Application intake/replay/corrections/audits/search/lifecycle checks passed; % existing identities checked. Issued fixture staging is not signing acceptance.',identity_count;
end $$;
rollback;
select 'Application acceptance rolled back' as result;
